def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    # Tiles are 2x2 squares (color 1) and L triominoes, colored by the missing corner.
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                pieces.append((1, frozenset(box)))
            corner_colors = [
                ((r, c), 2),        # missing top-left
                ((r + 1, c), 3),    # missing bottom-left
                ((r, c + 1), 4),    # missing top-right
                ((r + 1, c + 1), 5),# missing bottom-right
            ]
            for missing, color in corner_colors:
                piece = box - {missing}
                if piece <= cells:
                    pieces.append((color, frozenset(piece)))
    by_cell = {p: [] for p in cells}
    for color, piece in pieces:
        for p in piece:
            by_cell[p].append((color, piece))

    def cover(remaining, out):
        if not remaining:
            return out
        p = min(remaining, key=lambda x: sum(piece <= remaining for _, piece in by_cell[x]))
        for color, piece in by_cell[p]:
            if piece <= remaining:
                result = cover(remaining - piece, out + [(color, piece)])
                if result is not None:
                    return result
        return None

    solution = cover(frozenset(cells), [])
    if solution is None:
        return [row[:] for row in grid]
    output = [[0] * w for _ in range(h)]
    for color, piece in solution:
        for r, c in piece:
            output[r][c] = color
    return output
